def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    # Remove duplicates and sort
    unique_nums = sorted(set(nums))

    result = []
    i = 0
    n = len(unique_nums)

    while i < n:
        start = unique_nums[i]
        # Find the end of the current consecutive sequence
        j = i
        while j + 1 < n and unique_nums[j + 1] == unique_nums[j] + 1:
            j += 1

        # Check if the run is 3 or more numbers
        if j - i + 1 >= 3:
            result.append(f"{start}..{unique_nums[j]}")
        else:
            # Add individual numbers
            for k in range(i, j + 1):
                result.append(str(unique_nums[k]))

        i = j + 1

    return ",".join(result)
